using System.IO;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;
using RAWSelectionAssistant.Services;using RAWSelectionAssistant.ViewModels;using RAWSelectionAssistant.Views;
using static RAWSelectionAssistant.WpfTests.RuntimeCorrectionWpfTests;
namespace RAWSelectionAssistant.WpfTests;
[TestClass][DoNotParallelize]public sealed class DarkroomImportTests
{
 [TestMethod]public void NativePickerUsesIndependentStateAndKeepsRealFileSelection(){var d=WpfDialogService.CreateFileDialog("photos","Images|*.png",true);Assert.AreEqual(WpfDialogService.ImageOpenDialogClient,d.ClientGuid);Assert.AreNotEqual(Guid.Empty,d.ClientGuid);Assert.IsTrue(d.RestoreDirectory);Assert.IsTrue(d.CheckFileExists);Assert.IsTrue(d.Multiselect);Assert.AreEqual("Images|*.png",d.Filter);}
 [TestMethod]public Task ImportCancelAndPickerFailureRemainRetryable()=>RunSta(async()=>{EnsureTestApplication();var r=Root();try{var dialogs=new Dialogs();using var vm=new ReferenceColorWorkspaceViewModel(dialogs);await vm.LoadTargetAsync(Image(r,"original.png",70));var old=vm.ActiveTarget;await vm.ChooseTargetCommand.ExecuteAsync(null);Assert.AreSame(old,vm.ActiveTarget);StringAssert.Contains(vm.StatusText,"已取消");Assert.IsTrue(vm.ChooseTargetCommand.CanExecute(null));dialogs.Fail=true;await vm.ChooseTargetCommand.ExecuteAsync(null);Assert.AreSame(old,vm.ActiveTarget);Assert.AreEqual(1,dialogs.Errors);StringAssert.Contains(vm.StatusText,"导入未完成");Assert.IsFalse(vm.IsLoading);Assert.IsTrue(vm.ChooseTargetCommand.CanExecute(null));dialogs.Fail=false;dialogs.Files=[Image(r,"new.png",140)];await vm.ChooseTargetCommand.ExecuteAsync(null);Assert.AreEqual(2,vm.Targets.Count);Assert.AreEqual("new.png",vm.ActiveTarget!.FileName);Assert.IsFalse(vm.IsLoading);Assert.IsTrue(vm.ChooseTargetCommand.CanExecute(null));}finally{Directory.Delete(r,true);}});
 [TestMethod]public Task ActualImportButtonLoadsTwoDifferentPhotosAndDeduplicates()=>RunSta(async()=>{EnsureTestApplication();var r=Root();try{var a=Image(r,"a.png",30);var b=Image(r,"b.png",180);var dialogs=new Dialogs{Files=[a,b,a]};using var vm=new ReferenceColorWorkspaceViewModel(dialogs);var page=new PhotoGradePageView{DataContext=vm};page.Measure(new Size(1366,768));page.Arrange(new Rect(0,0,1366,768));page.UpdateLayout();var button=(Button)page.FindName("PhotoImport");Assert.AreSame(vm.ChooseTargetCommand,button.Command);await vm.ChooseTargetCommand.ExecuteAsync(null);Assert.AreEqual(2,vm.Targets.Count);Assert.AreEqual("a.png",vm.ActiveTarget!.FileName);Assert.IsNotNull(vm.Editor.SourceImage);Assert.AreSame(vm.Targets[0],vm.ActiveTarget);await vm.ActivateTargetCommand.ExecuteAsync(vm.Targets[1]);Assert.AreEqual("b.png",vm.ActiveTarget.FileName);Assert.IsNotNull(page.FindName("ImportStatus"));page.DataContext=null;}finally{Directory.Delete(r,true);}});
 static string Root(){var p=Path.Combine(Path.GetTempPath(),"R3Import-"+Guid.NewGuid());Directory.CreateDirectory(p);return p;}
 static string Image(string r,string n,byte c){var p=Path.Combine(r,n);var image=BitmapSource.Create(32,24,96,96,PixelFormats.Rgb24,null,Enumerable.Repeat(c,32*24*3).ToArray(),96);StudioQuickExport.Encode(image,p,p,StudioExportFormat.Png);return p;}
 sealed class Dialogs:IDialogService{public string[] Files=[];public bool Fail;public int Errors;public string? ChooseFolder(string t,string? initialDirectory=null)=>null;public IReadOnlyList<string> ChooseFiles(string t,string f,bool multiselect=true){if(Fail)throw new IOException("picker failed");return Files;}public string? ChooseSaveFile(string t,string f,string e,string? suggestedFileName=null)=>null;public IReadOnlyList<string>? ManageQuickTools(IReadOnlyList<string> i)=>null;public void ShowInfo(string m){}public void ShowError(string m){Errors++;}public bool Confirm(string m,string t)=>false;public HelpAction ShowHelp()=>HelpAction.None;public void ShowFeedback(){}public RAWSelectionAssistant.Core.Models.RawFileEntry? ChooseRawCandidate(IReadOnlyList<RAWSelectionAssistant.Core.Models.RawFileEntry> c)=>null;public bool ShowMediaDetails(RAWSelectionAssistant.Core.Models.MediaSelectionItem i,bool a)=>false;public void RevealFile(string p){}}
}
